def copy_graph(original, *, scope='ordinary'):
    """Copy only dependencies of raw patches with a proven common port context."""
    if scope not in ('ordinary', 'compound', 'boundary'):
        raise ValueError('Unknown prepared-port scope: '+str(scope))
